import sys

def min_spots(n, H):
    if n <= H:
        return 1
    if H == 1:
        return n
    k = (H + 1) // 2
    if n <= k * (k + 1):
        return 2
    return 2 + (n - k * (k + 1) - 1) // (2 * H)

if __name__ == "__main__":
    n, H = map(int, sys.stdin.read().split())
    print(min_spots(n, H))
